from typing import List
from functools import lru_cache

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words=set(wordDict)
        @lru_cache(None)
        def build(i):
            if i==len(s):return ('',)
            out=[]
            for word in words:
                if s.startswith(word,i):
                    for suffix in build(i+len(word)):out.append(word if not suffix else word+' '+suffix)
            return tuple(out)
        return list(build(0))

import java.util.*;

class Solution {
    private String s;private Set<String>words;private Map<Integer,List<String>>memo;
    public List<String> wordBreak(String s,List<String> wordDict){this.s=s;words=new HashSet<>(wordDict);memo=new HashMap<>();return build(0);}
    private List<String> build(int i){if(memo.containsKey(i))return memo.get(i);List<String>out=new ArrayList<>();if(i==s.length()){out.add("");return out;}for(String w:words)if(s.startsWith(w,i))for(String suffix:build(i+w.length()))out.add(suffix.isEmpty()?w:w+" "+suffix);memo.put(i,out);return out;}
